async def seed_lessons(db: AsyncSession):
    result = await db.execute(select(Concept))
    concepts = {c.slug: {"id": c.id, "difficulty": c.difficulty} for c in result.scalars().all()}

    existing_result = await db.execute(select(Lesson.slug))
    existing_slugs = {row[0] for row in existing_result.all()}

    created = 0
    skipped = 0
    for lesson_data in LESSONS_SEED:
        concept_slug = lesson_data.get("concept_slug")
        if lesson_data["slug"] in existing_slugs:
            skipped += 1
            continue

        concept_info = concepts.get(concept_slug)
        if not concept_info:
            skipped += 1
            continue

        lesson = Lesson(
            id=str(uuid.uuid4()),
            concept_id=concept_info["id"],
            title=lesson_data["title"],
            slug=lesson_data["slug"],
            description=lesson_data.get("description"),
            difficulty=concept_info["difficulty"],
            hook=lesson_data.get("hook"),
            problem=lesson_data.get("problem"),
            explanation=lesson_data.get("explanation"),
            real_world_example=lesson_data.get("real_world_example"),
            summary=lesson_data.get("summary"),
            curiosity_hook=lesson_data.get("curiosity_hook"),
            dialogue=lesson_data.get("dialogue", []),
            learning_objectives=lesson_data.get("learning_objectives", []),
            quiz_questions=lesson_data.get("quiz_questions", []),
            approved=True,
            total_watches=0,
            average_completion=0.0,
            average_quiz_score=0.0,
        )
        db.add(lesson)
        created += 1

    await db.commit()
    return {"status": "seeded", "lessons_created": created, "skipped": skipped}

